package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTax decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64             // PIC 9(3) len=3 = 0
var WsIncEd string            // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string            // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string            // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string          // PIC ZZ,ZZZ,ZZ9.99 len=13

var FileRec TaxRec
var taxFile *os.File
var taxScanner *bufio.Scanner

func InputDone() bool {
	return WsEofFlag == "Y"
}

func fitDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	neg := d.IsNegative()
	abs := d.Abs()
	s := abs.StringFixed(scale)
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPart = parts[0]
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = ""
		}
		if len(fracPart) < int(scale) {
			fracPart = fracPart + strings.Repeat("0", int(scale)-len(fracPart))
		}
		if len(fracPart) > int(scale) {
			fracPart = fracPart[:int(scale)]
		}
	} else {
		intPart = s
		fracPart = ""
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var ns string
	if scale > 0 {
		ns = intPart + "." + fracPart
	} else {
		ns = intPart
	}
	nd, err := decimal.NewFromString(ns)
	if err != nil {
		return decimal.Zero
	}
	if neg && !nd.IsZero() {
		nd = nd.Neg()
	}
	return nd
}

func formatEdited(d decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	fracLen := 0
	if dotIdx >= 0 {
		for _, ch := range pic[dotIdx+1:] {
			if ch == 'Z' || ch == '9' {
				fracLen++
			}
		}
	}
	var intPicPart string
	if dotIdx >= 0 {
		intPicPart = pic[:dotIdx]
	} else {
		intPicPart = pic
	}
	nInt := 0
	for _, ch := range intPicPart {
		if ch == 'Z' || ch == '9' {
			nInt++
		}
	}
	dt := d.Truncate(int32(fracLen))
	neg := dt.IsNegative()
	if neg {
		dt = dt.Neg()
	}
	scaled := dt.Shift(int32(fracLen)).Truncate(0)
	s := scaled.StringFixed(0)
	// s should be plain digits (non-negative)
	// guard against sign/exponent just in case
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	// remove any sign
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	// if exponential (should not happen), fallback
	if strings.ContainsAny(s, ".eE") {
		// fallback via string fixed of dt
		s2 := dt.StringFixed(int32(fracLen))
		s2 = strings.ReplaceAll(s2, ".", "")
		s2 = strings.ReplaceAll(s2, "-", "")
		s2 = strings.ReplaceAll(s2, "+", "")
		s = s2
		if s == "" {
			s = "0"
		}
	}
	var intRaw, fracRaw string
	if fracLen > 0 {
		if len(s) <= fracLen {
			intRaw = "0"
			fracRaw = strings.Repeat("0", fracLen-len(s)) + s
		} else {
			fracRaw = s[len(s)-fracLen:]
			intRaw = s[:len(s)-fracLen]
		}
	} else {
		intRaw = s
		fracRaw = ""
	}
	if len(intRaw) > nInt {
		intRaw = intRaw[len(intRaw)-nInt:]
	}
	intPadded := strings.Repeat("0", nInt-len(intRaw)) + intRaw
	picRunes := []rune(pic)
	out := make([]rune, len(picRunes))
	intPos := 0
	fracPos := 0
	suppressed := true
	for i, p := range picRunes {
		switch p {
		case 'Z':
			isFrac := dotIdx >= 0 && i > dotIdx
			if isFrac {
				out[i] = rune(fracRaw[fracPos])
				fracPos++
			} else {
				dch := intPadded[intPos]
				intPos++
				if suppressed && dch == '0' {
					out[i] = ' '
				} else {
					out[i] = rune(dch)
					suppressed = false
				}
			}
		case '9':
			isFrac := dotIdx >= 0 && i > dotIdx
			if isFrac {
				out[i] = rune(fracRaw[fracPos])
				fracPos++
			} else {
				dch := intPadded[intPos]
				intPos++
				out[i] = rune(dch)
			}
		case ',':
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case '.':
			out[i] = '.'
		default:
			out[i] = p
		}
	}
	if neg {
		firstDigit := -1
		for i, ch := range out {
			if ch >= '0' && ch <= '9' {
				firstDigit = i
				break
			}
		}
		if firstDigit > 0 {
			placed := false
			for j := firstDigit - 1; j >= 0; j-- {
				if out[j] == ' ' {
					out[j] = '-'
					placed = true
					break
				}
			}
			if !placed {
				// no space found, overwrite first char if possible
				if out[0] == ' ' {
					out[0] = '-'
				}
			}
		} else if firstDigit == 0 {
			// no room for sign; leave as is
		}
	}
	return string(out)
}

func parseIncomeField(s8 string) decimal.Decimal {
	t := strings.TrimSpace(s8)
	if t == "" {
		return decimal.Zero
	}
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	// keep digits only (file stores digits only)
	var b strings.Builder
	for _, r := range t {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	ds := b.String()
	if ds == "" {
		return decimal.Zero
	}
	// ds is integer of cents
	d, err := decimal.NewFromString(ds)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(-2)
	if neg && !d.IsZero() {
		d = d.Neg()
	}
	return d
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// treat missing file as empty per LINE SEQUENTIAL? report error if truly missing?
		// To match batch behaviour, treat as empty (no records) if not found,
		// but if error is not NotExist, report it.
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
			countVal := ((WsCount % 1000) + 1000) % 1000
			countStr := fmt.Sprintf("%03d", countVal)
			fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
			return
		}
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	taxFile = f
	taxScanner = bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	taxScanner.Buffer(buf, maxCap)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	taxFile.Close()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countVal := ((WsCount % 1000) + 1000) % 1000
	countStr := fmt.Sprintf("%03d", countVal)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func ReadPara() {
	if taxScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if taxScanner.Scan() {
		line := taxScanner.Text()
		// Scanner strips trailing \r; ensure \r removed
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		recStr := line
		if len(recStr) < 13 {
			recStr = recStr + strings.Repeat(" ", 13-len(recStr))
		} else if len(recStr) > 13 {
			recStr = recStr[:13]
		}
		FileRec.TrId = recStr[0:5]
		incStr := recStr[5:13]
		FileRec.TrIncome = parseIncomeField(incStr)
	} else {
		if err := taxScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	d10000 := decimal.New(1000000, -2)
	d40000 := decimal.New(4000000, -2)
	d1000 := decimal.New(100000, -2)
	d7000 := decimal.New(700000, -2)
	d10pct := decimal.New(10, -2)
	d20pct := decimal.New(20, -2)
	d30pct := decimal.New(30, -2)
	if FileRec.TrIncome.Cmp(d10000) <= 0 {
		tmp := FileRec.TrIncome.Mul(d10pct)
		tmp = tmp.Round(2)
		WsTax = fitDecimal(tmp, 7, 2)
	} else {
		if FileRec.TrIncome.Cmp(d40000) <= 0 {
			tmp := FileRec.TrIncome.Sub(d10000).Mul(d20pct)
			tmp = d1000.Add(tmp)
			tmp = tmp.Round(2)
			WsTax = fitDecimal(tmp, 7, 2)
		} else {
			tmp := FileRec.TrIncome.Sub(d40000).Mul(d30pct)
			tmp = d7000.Add(tmp)
			tmp = tmp.Round(2)
			WsTax = fitDecimal(tmp, 7, 2)
		}
	}
	tmpNet := FileRec.TrIncome.Sub(WsTax)
	tmpNet = tmpNet.Truncate(2)
	WsNet = fitDecimal(tmpNet, 7, 2)
	tmpTot := WsTotalTax.Add(WsTax)
	tmpTot = tmpTot.Truncate(2)
	WsTotalTax = fitDecimal(tmpTot, 9, 2)
	WsCount = (WsCount + 1) % 1000
	if WsCount < 0 {
		WsCount += 1000
	}
	WsIncEd = formatEdited(FileRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", FileRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func main() {
	MainPara()
}
